import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), p = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Every cut between i and i+1 adds a[i] + a[i+1] on top of the fixed ends.
        long[] cuts = new long[n - 1];
        for (int i = 0; i + 1 < n; i++) cuts[i] = a[i] + a[i + 1];
        Arrays.sort(cuts);
        long base = a[0] + a[n - 1], low = base, high = base;
        int m = cuts.length;
        for (int i = 0; i < p - 1; i++) {
            low += cuts[i];
            high += cuts[m - 1 - i];
        }
        System.out.println(low + " " + high);
    }
}

package main

import (
