	n, p := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	// Every cut between i and i+1 adds a[i] + a[i+1] on top of the fixed ends.
	cuts := make([]int64, 0, n)
	for i := 0; i+1 < n; i++ {
		cuts = append(cuts, a[i]+a[i+1])
	}
	slices.Sort(cuts)
	base := a[0] + a[n-1]
	low, high := base, base
	m := len(cuts)
	for i := 0; i < p-1; i++ {
		low += cuts[i]
		high += cuts[m-1-i]
	}
	fmt.Println(low, high)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
